const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const defaultShape=()=>[{u:0,v:0},{u:.05,v:30},{u:.2,v:45},{u:.45,v:28},{u:.7,v:40},{u:.95,v:35},{u:1,v:0}];
const newRoute=name=>({id:uid(),name,points:[],endpoints:{home:null,destination:null},endpointsLocked:false,paths:null,trips:[],format:'csv'});
const newTrip=r=>({id:uid(),name:'Trip '+(r.trips.length+1),direction:'outbound',departure:today+'T07:00:00',arrival:today+'T07:30:00',vehicle:'jeepney',averageSpeed:25,profile:defaultShape(),speedVariation:10,stopVariation:20,seed:42,recordingStart:null,recordingEnd:null,points:[],stops:{},path:null});
let state={version:4,server:'https://router.project-osrm.org',routes:[newRoute('Route 1')]},active,tripId=null,mode='waypoint',preview=null,model=null,buildToken=0,controller=null,playTimer=null,toastTimer,drag=null,additions=[],playMarker=null;
const current=()=>state.routes.find(r=>r.id===active),trip=()=>current()?.trips.find(t=>t.id===tripId);
function validCoord(p){return Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&Math.abs(p[0])<=180&&Math.abs(p[1])<=90;}
function validId(id){return typeof id==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(id);}
function validateServer(v){let u;try{u=new URL(v);}catch{throw Error('Enter a valid OSRM server URL.');}if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error('Use HTTPS for OSRM, or HTTP on localhost.');if(u.username||u.password||u.search||u.hash)throw Error('Use the OSRM base URL without credentials, query or fragment.');}
function validateTrip(t){if(!validId(t.id)||typeof t.name!=='string'||t.name.length>80||!['outbound','return'].includes(t.direction))throw Error('Invalid trip name or direction.');tripSeconds(t);normalizeShape(t.profile);if(t.vehicle!==undefined&&!VEHICLES[t.vehicle]||t.averageSpeed!==undefined&&(!Number.isFinite(t.averageSpeed)||t.averageSpeed<1||t.averageSpeed>80))throw Error('Invalid vehicle or average speed.');if(!Number.isInteger(t.seed)||t.seed<1||t.seed>2147483647||!Number.isFinite(t.speedVariation)||t.speedVariation<0||t.speedVariation>40||!Number.isFinite(t.stopVariation)||t.stopVariation<0||t.stopVariation>80||!t.stops||typeof t.stops!=='object'||Array.isArray(t.stops))throw Error('Invalid trip variation or stop settings.');for(const [id,s] of Object.entries(t.stops))if(!validId(id)||!s||typeof s.enabled!=='boolean'||!Number.isFinite(s.duration)||s.duration<0||s.duration>7200||s.passengerToken!==undefined&&(typeof s.passengerToken!=='string'||s.passengerToken.length>200))throw Error('Invalid trip stop duration.');}
function validatePath(path,count){if(!path||!Array.isArray(path.coords)||path.coords.length>100000)throw Error('Invalid saved road geometry.');geometry(path.coords);if(!Array.isArray(path.snapped)||path.snapped.length!==count||path.snapped.some(x=>!validCoord(x)))throw Error('Invalid saved road waypoints.');}
function validateProject(source){const s=migrateProject(source);if(s.version!==4||!Array.isArray(s.routes)||!s.routes.length||s.routes.length>50)throw Error('Not a supported Trip Studio project.');validateServer(s.server);const ids=new Set();for(const r of s.routes){if(!validId(r.id)||ids.has(r.id)||typeof r.name!=='string'||r.name.length>80||!Array.isArray(r.points)||r.points.length>2||typeof r.endpointsLocked!=='boolean'||!Array.isArray(r.trips)||r.trips.length>1000||!['csv','json','gpx'].includes(r.format))throw Error('Invalid route in project.');ids.add(r.id);for(const p of r.points)if(!validId(p.id)||p.kind!=='waypoint'||!validCoord(p.coord)||typeof p.name!=='string')throw Error('Invalid fixed endpoint.');initializeEndpoints(r);if(r.endpointsLocked)endpoints(r,true);if(r.paths)for(const d of ['outbound','return'])validatePath(r.paths[d],2);const tids=new Set();for(const t of r.trips){validateTrip(t);if(tids.has(t.id)||!Array.isArray(t.points)||t.points.length>98)throw Error('Invalid trip map points.');tids.add(t.id);const pids=new Set();for(const p of [t.recordingStart,t.recordingEnd].filter(Boolean)){if(!validId(p.id)||!validCoord(p.coord)||p.kind!=='waypoint'||typeof p.name!=='string'||pids.has(p.id)||Object.values(r.endpoints).includes(p.id))throw Error('Invalid trip recording endpoint.');pids.add(p.id);}recordingEndpoints(t);for(const p of t.points){if(!validId(p.id)||pids.has(p.id)||Object.values(r.endpoints).includes(p.id)||!['waypoint','stop'].includes(p.kind)||!validCoord(p.coord)||typeof p.name!=='string'||p.name.length>80)throw Error('Invalid trip detour or stop.');pids.add(p.id);}if(t.path)validatePath(t.path,tripPoints(r,t).length);}}return s;}

let migrated=false;
