for(const el of document.querySelectorAll('[data-stop-result]')){const e=model?.events.find(x=>x.id===el.dataset.stopResult);el.textContent=e?`${clock(e.onset)} → ${clock(e.end)} · seeded pause ${e.duration}s`:'This stop is not included or the schedule is invalid.';}
