const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)||'route';
function generateTrip(r,t,index){validateTrip(t);if(!t.path)throw Error('Update the road path for “'+t.name+'” first.');const sim=schedule({coords:t.path.coords,trip:t,stops:getStops(r,t),completion:tripCompletion(r,t)});if(sim.maxSpeed>160)throw Error('“'+t.name+'” needs '+sim.maxSpeed.toFixed(1)+' km/h. Move its arrival later or reshape its curve.');return {filename:'trip-'+String(index+1).padStart(4,'0')+'.'+r.format,tripId:t.id,name:t.name,direction:t.direction,sim};}
