function manifest(b){return {schemaVersion:4,source:'synthetic',generator:'LIGTAS Trip Studio 4.0',samplingIntervalSeconds:INTERVAL,inputTimezone:'Asia/Manila',timestampTimezone:'UTC',speedTimeAxis:'full elapsed trip time, including zero-speed stops',fitPolicy:'seeded speed shape scaled to road distance over departure-to-arrival time less explicit stops',samplingPolicy:'departure plus multiples of 10 seconds through arrival; no added endpoint if arrival is between samples',route:b.route,recordings:b.entries.map(e=>({file:recordingPath(e),tripId:e.tripId,name:e.name,direction:e.direction,departure:e.sim.start,arrival:e.sim.end,recordingStopsAt:e.sim.completion,seed:e.sim.seed,fitFactor:e.sim.fitFactor,maximumSpeedKmh:e.sim.maxSpeed,rows:e.sim.rows.length,stops:e.sim.events,speedControls:e.sim.controls}))};}
async function zipBatches(batches,name){const zip=new JSZip();for(let i=0;i<batches.length;i++){const b=batches[i],folder=zip.folder(String(i+1).padStart(2,'0')+'-'+slug(b.route.name));folder.folder('a-to-b');folder.folder('b-to-a');folder.file('manifest.json',JSON.stringify(manifest(b),null,2));folder.file('project.json',JSON.stringify({version:4,server:state.server,routes:[b.route]},null,2));for(const e of b.entries)folder.file(recordingPath(e),encode(e.sim.rows,b.route.format));}zip.file('README.txt','LIGTAS synthetic recordings. Each trip was manually added with its own direction, departure, arrival, speed shape, stop settings and seed. GPS timestamps use UTC at exact ten-second intervals. A non-grid arrival is documented in the manifest; the last GPS fix precedes it. Speed shape and seeded point variation are fitted to the road distance within the exact requested schedule. Stops consume elapsed time and appear at zero speed. Recordings are grouped into a-to-b/ and b-to-a/. Home (A) and Destination (B) are fixed route reference points. Every trip has its own recording start and end; recording ends at its routed recording end. Direction identifies the export folder. Each route manifest records the synthetic source, endpoints, directions and settings separately from neutral GPS recording files.\n');download(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),name);toast('ZIP downloaded · '+batches.reduce((n,b)=>n+b.entries.length,0)+' manually designed trips.');}
