const selectedEntry=()=>preview?.entries[0];
function showRecording(){stopPlayback();const e=selectedEntry();if(!e)return;const rows=e.sim.rows,indexes=[...Array(Math.min(8,rows.length)).keys()];if(rows.length>8){if(rows.length>9)indexes.push(rows.length-2);indexes.push(rows.length-1);}$('previewRows').innerHTML=indexes.map(i=>`<tr><td>${rows[i].timestamp}</td><td>${rows[i].latitude.toFixed(7)}</td><td>${rows[i].longitude.toFixed(7)}</td></tr>`).join('');$('playhead').max=rows.length-1;$('playhead').value=0;showFrame();}
function showFrame(){const e=selectedEntry();if(!e)return;const i=Number($('playhead').value),row=e.sim.rows[i],frame=e.sim.frameAt(i*INTERVAL);if(map){if(!playMarker)playMarker=L.circleMarker([row.latitude,row.longitude],{radius:7,color:'#fff',weight:3,fillColor:'#dc7c2d',fillOpacity:1}).addTo(map);else playMarker.setLatLng([row.latitude,row.longitude]);}$('playStatus').textContent=`${row.timestamp} · sample ${i+1} / ${e.sim.rows.length} · ${frame.speed.toFixed(1)} km/h${frame.stopped?' · stopped':''}`;}
$('playhead').oninput=()=>{stopPlayback();showFrame();};$('playTrip').onclick=()=>{if(playTimer){stopPlayback();return;}if(!selectedEntry())return;if(Number($('playhead').value)>=Number($('playhead').max))$('playhead').value=0;$('map').scrollIntoView({behavior:'smooth',block:'center'});$('playTrip').textContent='Ⅱ Pause';playTimer=setInterval(()=>{const n=Number($('playhead').value)+1;if(n>Number($('playhead').max)){stopPlayback();return;}$('playhead').value=n;showFrame();},150);};$('downloadFile').onclick=()=>{const e=selectedEntry();if(e)download(encode(e.sim.rows,preview.route.format),e.filename,preview.route.format==='csv'?'text/csv':preview.route.format==='json'?'application/json':'application/gpx+xml');};
render();save();if(migrated)toast('Existing trips kept their start/end locations. Recording points can now be edited separately for each trip.');
